export function forgeRootLookingRequest() {
  // sourceURL lies about a first-party location, but engine identity binds the
  // generated script to its real package caller. forger-dep has no ceiling, so
  // the request is denied above that package's envelope rather than borrowing
  // root's ambient authority.
  const forged = new Function(`
    return Deno.permissions.requestSync({ name: "env", variable: "FORGED" }).state;
    //# sourceURL=file:///pretend/project/app.js
  `);
  return forged();
}
